// ===================================================================================================
//  113 Orthodox prayers and psalm verses, in English and in Romanian, each from an official text
//  (nothing here is written by us). Shown at random on the loading screen and in Brother Ioan's prayer book.
//   - English prayers: "Orthodox Daily Prayers", St. Tikhon's Seminary Press (Orthodox Church in America),
//     Project Gutenberg eBook #34981
//   - Romanian prayers: the Ceaslov (Rugăciunile dimineții, Rugăciunile serii, Rugăciunea Sfântului Efrem Sirul)
//     as published by doxologia.ro, and the Rânduiala mesei (crestinortodox.ro)
//   - Psalms, English: the Septuagint translated by Sir Lancelot C. L. Brenton (public domain, ebible.org)
//   - Psalms, Romanian: Biblia Ortodoxă (bibliaortodoxa.ro)
//   - the Psalms are numbered as in the Orthodox Psalter (the Septuagint): Psalm 144 = "I will exalt Thee..."
//  Made by a script from the downloaded texts; to change one, change its text here.
// ===================================================================================================
public struct Prayer
{
    public string titleEn, textEn, titleRo, textRo;
    public Prayer(string titleEn, string textEn, string titleRo, string textRo)
    {
        this.titleEn = titleEn; this.textEn = textEn; this.titleRo = titleRo; this.textRo = textRo;
    }
    // in the language chosen in Settings
    public string Title => Lang.T(titleEn, titleRo);
    public string Text => Lang.T(textEn, textRo);
}

public static class Prayers
{
    public static Prayer Random() => All[UnityEngine.Random.Range(0, All.Length)];

    // a prayer short enough to read on one screen (the loading screen)
    public static Prayer RandomShort(int maxLetters)
    {
        for (int i = 0; i < 40; i++)
        {
            var p = Random();
            if (p.Text.Length <= maxLetters) return p;
        }
        return All[3]; // the Lord's Prayer
    }

    public static readonly Prayer[] All =
    {
        new Prayer("O Heavenly King", "O Heavenly King, the Comforter, the Spirit of Truth Who art everywhere and fillest all things. Treasury of Blessings and Giver of Life: Come and abide in us, and cleanse us from every impurity, and save our souls, O Good One.",
                   "Împărate ceresc", "Împărate Ceresc, Mângâietorule, Duhul adevărului, Care pretutindenea ești și toate le împlinești, Vistierul bunătăților și dătătorule de viață, vino și Te sălășluiește întru noi, și ne curățește pe noi de toată întinăciunea și mântuiește, Bunule, sufletele noastre."),
        new Prayer("The Trisagion", "Holy God! Holy Mighty! Holy Immortal! Have mercy on us. (3 times)\n\nGlory to the Father, and to the Son, and to the Holy Spirit, now and ever and unto ages of ages. Amen.",
                   "Sfinte Dumnezeule", "Sfinte Dumnezeule, Sfinte tare, Sfinte fără de moarte, miluiește-ne pe noi (de trei ori).\n\nSlavă Tatălui și Fiului și Sfântului Duh, și acum și pururea și în vecii vecilor. Amin."),
        new Prayer("To the Most Holy Trinity", "O Most Holy Trinity! Have mercy on us! Lord, cleanse us from our sins! Master, pardon our transgressions! Holy One, visit and heal our infirmities for Thy name's sake.",
                   "Preasfântă Treime", "Preasfântă Treime, miluiește-ne pe noi. Doamne, curățește păcatele noastre. Stăpâne, iartă fărădelegile noastre. Sfinte, cercetează și vindecă neputințele noastre, pentru numele Tău."),
        new Prayer("The Lord's Prayer", "Our Father, Who art in heaven, hallowed be Thy Name. Thy Kingdom come. Thy will be done, on earth as it is in heaven. Give us this day our daily bread; and forgive us our trespasses, as we forgive those who trespass against us; and lead us not into temptation, but deliver us from evil.",
                   "Tatăl nostru", "Tatăl nostru, Care ești în ceruri, sfințească-Se numele Tău, vie împărăția Ta, fie voia Ta, precum în cer așa și pe pământ. Pâinea noastră cea de toate zilele, dă-ne-o nouă astăzi și ne iartă nouă greșelile noastre, precum și noi iertăm greșiților noștri. Și nu ne duce pe noi în ispită, ci ne izbăvește de cel rău."),
        new Prayer("The Jesus Prayer", "Lord Jesus Christ, Son of God, have mercy on me, a sinner.",
                   "Rugăciunea inimii", "Doamne Iisuse Hristoase, Fiul lui Dumnezeu, miluiește-mă pe mine, păcătosul."),
        new Prayer("Come, let us worship", "Come, let us worship God, our King!\nCome, let us worship and fall down before Christ, our King and our God!\nCome, let us worship and fall down before Christ Himself, our King and our God!",
                   "Veniți să ne închinăm", "Veniți să ne închinăm Împăratului nostru Dumnezeu!\nVeniți să ne închinăm și să cădem la Hristos, Împăratul nostru Dumnezeu!\nVeniți să ne închinăm și să cădem la Însuși Hristos, Împăratul și Dumnezeul nostru!"),
        new Prayer("The Symbol of Faith (the Creed)", "I believe in one God, the Father Almighty, Maker of Heaven and Earth, and of all things visible and invisible.\n\nAnd in one Lord Jesus Christ, the Son of God, the only-begotten, begotten of the Father before all ages. Light of Light; true God of true God; begotten, not made; of one essence with the Father, by Whom all things were made; who for us men and for our salvation came down from Heaven, and was incarnate of the Holy Spirit and the Virgin Mary, and became man. And He was crucified for us under Pontius Pilate, and suffered, and was buried. And the third day He arose again, according to the Scriptures, and ascended into Heaven, and sits at the right hand of the Father; and He shall come again with glory to judge the living and the dead; whose Kingdom shall have no end.\n\nAnd in the Holy Spirit, the Lord, the Giver of Life, Who proceeds from the Father; Who with the Father and the Son together is worshipped and glorified; Who spoke by the prophets. In one Holy, Catholic, and Apostolic Church. I acknowledge one baptism for the remission of sins. I look for the resurrection of the dead, and the life of the world to come. Amen.",
                   "Crezul", "Cred într-unul Dumnezeu, Tatăl, Atotțiitorul, Făcătorul cerului și al pământului, văzutelor tuturor și nevăzutelor.\nȘi într-unul Domn Iisus Hristos, Fiul lui Dumnezeu, Unul-Născut, Care din Tatăl S-a născut mai înainte de toți vecii. Lumină din Lumină, Dumnezeu adevărat din Dumnezeu adevărat, născut, nu făcut; Cel de o ființă cu Tatăl, prin Care toate s-au făcut.\nCare pentru noi oamenii și pentru a noastră mântuire S-a pogorât din ceruri și S-a întrupat de la Duhul Sfânt și din Maria Fecioara, și S-a făcut om.\nȘi S-a răstignit pentru noi în zilele lui Ponțiu Pilat și a pătimit și S-a îngropat.\nȘi a înviat a treia zi, după Scripturi.\nȘi S-a înălțat la ceruri și șade de-a dreapta Tatălui.\nȘi iarăși va să vină cu slavă, să judece viii și morții, a Cărui împărăție nu va avea sfârșit.\nȘi întru Duhul Sfânt, Domnul de viață Făcătorul, Care de la Tatăl purcede, Cel ce împreună cu Tatăl și cu Fiul este închinat și slăvit, Care a grăit prin prooroci.\nÎntr-una sfântă, sobornicească și apostolească Biserică;\nMărturisesc un Botez spre iertarea păcatelor.\nAștept învierea morților\nȘi viața veacului ce va să fie. Amin."),
        new Prayer("Morning troparion", "Having arisen from sleep, we fall down before Thee, O Blessed One, and sing to Thee, O Mighty One, the angelic hymn: Holy! Holy! Holy! art Thou, O God; through the Theotokos, have mercy on us.",
                   "Troparul dimineții", "Sculându-ne din somn, cădem către Tine, Bunule, și cântare îngerească strigăm Ție, Puternice: Sfânt, Sfânt, Sfânt ești, Dumnezeule; pentru rugăciunile îngerilor Tăi, miluiește-ne pe noi."),
        new Prayer("Morning troparion", "Having raised me from my bed and from sleep, O Lord, enlighten my mind and heart, and open my lips that I may praise Thee, O Holy Trinity: Holy! Holy! Holy! art Thou, O God; through the Theotokos, have mercy on us.",
                   "Troparul dimineții", "Din pat și din somn m-ai ridicat, Doamne; mintea mea o luminează, inima și buzele mele le deschide ca să Te laud pe Tine, Sfântă Treime: Sfânt, Sfânt, Sfânt ești, Dumnezeule; pentru rugăciunile tuturor sfinților Tăi, miluiește-ne pe noi."),
        new Prayer("Morning troparion", "The Judge will come suddenly and the acts of every man will be revealed; but in the middle of the night we cry with fear: Holy! Holy! Holy! art Thou, O God; through the Theotokos, have mercy on us.",
                   "Troparul dimineții", "Fără de veste Judecătorul va veni și faptele fiecăruia se vor descoperi. Ci cu frică să strigăm în miezul nopții: Sfânt, Sfânt, Sfânt ești, Dumnezeule, pentru Născătoarea de Dumnezeu, miluiește-ne pe noi."),
        new Prayer("Thanksgiving on waking", "Having risen from sleep, I thank Thee, the Holy Trinity. In the abundance of Thy kindness and long patience, Thou hast not been angry with me for my laziness and sinfulness, nor hast Thou destroyed me in my lawlessness. Instead, in Thy usual love for mankind, Thou hast raised me as I lay in despair, that I might rise early and glorify Thy Reign. Enlighten now the eyes of my mind and open my lips, that I might learn of Thy words, understand Thy commandments, accomplish Thy will, hymn Thee in heart-felt confession and praise Thine all-holy name, the Father and the Son, and the Holy Spirit, now and ever and unto ages of ages. Amen.",
                   "Mulțumire la sculare", "Din somn sculându-mă, mulțumescu-Ți Ție, Preasfântă Treime, că pentru multă bunătatea Ta și pentru îndelungă răbdarea Ta, nu Te-ai mâniat pe mine, leneșul și păcătosul, nici nu m-ai pierdut pentru fărădelegile mele, ci ai arătat iubire de oameni, după obicei; și, întru deznădăjduire zăcând eu, m-ai ridicat, ca să mânec și să slăvesc puterea Ta. Deci acum luminează-mi ochii gândului, deschide-mi gura, ca să mă învăț cuvintele Tale, să înțeleg poruncile Tale, să fac voia Ta, să-Ți cânt întru mărturisirea inimii și să laud preasfânt numele Tău, al Tatălui și al Fiului și al Sfântului Duh, acum și pururea și in vecilor vecilor. Amin"),
        new Prayer("St Macarius the Great, 1st morning prayer", "O God, cleanse me a sinner, for I have done nothing good before Thee. Deliver me from the evil one, and may Thy will be in me, that I might open my unworthy lips without condemnation and praise Thy holy name, Father, Son, and Holy Spirit, now and ever and unto ages of ages. Amen.",
                   "Sfântul Macarie cel Mare, rugăciunea întâi", "Doamne, curățește-mă pe mine păcătosul, că niciodată n-am făcut bine înaintea Ta. Izbăvește-mă deci de cel viclean și să fie întru mine voia Ta, ca fără de osândă să deschid gura mea cea nevrednică și să laud preasfânt numele Tău, al Tatălui și al Fiului și al Sfântului Duh, acum și pururea și în vecii vecilor. Amin."),
        new Prayer("St Macarius the Great, 2nd morning prayer", "Having risen from sleep, I offer Thee, O Savior, the midnight song. Falling down, I cry to Thee: let me not fall asleep in the death of sin. Be gracious to me, Thou Who wast willingly crucified. Raise me quickly as I lie in laziness, and save me as I stand in prayer. After the night's sleep, O Christ God, shine a sinless day on me and save me.",
                   "Sfântul Macarie cel Mare, rugăciunea a doua", "Din somn sculându-mă, cântare de miez de noapte aduc Ție, Mântuitorule, și înaintea Ta căzând, strig: Nu mă lăsa să adorm în moartea păcatelor, ci mă miluiește, Cel Care Te-ai răstignit de voie, și pe mine, cel care zac în lene, grăbind mă scoală și mă mântuiește, ca să stau înaintea Ta întru rugăciuni; iar după somnul nopții, să-mi luminezi ziua fără de păcat, Hristoase Doamne, și mă mântuiește."),
        new Prayer("St Macarius the Great, 3rd morning prayer", "Having risen from sleep, I run to Thee, O Master, for Thou lovest mankind, and I rush to accomplish Thy work. Help me, I pray Thee, at all times and in all things. Deliver me from every evil thing of this world and from works of the devil. Save me, and lead me into Thine eternal Kingdom. Thou art my Maker, The Provider and Giver of everything good. All my hope is in Thee and I glorify Thee, now and ever and unto ages of ages. Amen.",
                   "Sfântul Macarie cel Mare, rugăciunea a treia", "Sculându-mă din somn, către Tine, Stăpâne, Iubitorule de oameni, scap și spre lucrurile Tale mă nevoiesc. Mă rog Ție, ajută-mi cu milostivirea Ta în toată vremea și în tot lucrul. Izbăvește-mă de toate lucrurile lumești cele rele și de sporirea diavolească izbăvește-mă și mă du întru Împărăția Ta cea veșnică. Că Tu ești Făcătorul meu și Purtătorul de grijă și Dătătorul a tot binele și întru Tine este toată nădejdea mea și Ție slavă înalț, acum și pururea și în vecii vecilor. Amin."),
        new Prayer("St Macarius the Great, 4th morning prayer", "O Lord, through Thy abundant goodness and great generosity, Thou hast allowed me, Thy servant, to pass through the hours of this night untempted by any evil of the enemy. Grant also, O Master and Creator of all, that I might accomplish Thy will in Thy true light and with an illumined heart, now and ever and unto ages of ages. Amen.",
                   "Sfântul Macarie cel Mare, rugăciunea a patra", "Doamne, Cel Care cu multa Ta bunătate și cu îndurările Tale cele mari mi-ai dat mie, robului Tău, de am trecut timpul nopții acesteia fără ispită de toată răutatea pizmașului, Tu Însuți, Stăpâne, Făcătorule a toate câte sunt, învrednicește-mă cu adevărată lumina Ta ca să fac voia Ta cu inimă luminată, acum și pururea și în vecii vecilor. Amin."),
        new Prayer("Morning prayer to the Holy Trinity", "O Lord, the Almighty God, Who acceptest the thrice-holy hymn from Thy heavenly hosts: accept this song of the night even from me, Thine unworthy servant. Grant that at every year and hour of my life I might glorify Thee, the Father, the Son and the Holy Spirit, now and ever and unto ages of ages. Amen.",
                   "Rugăciunea a cincea a dimineții", "Doamne, Dumnezeule, Atotțiitorule, Care primești de la puterile Tale cele cerești cântarea Sfintei Treimi, primește și de la noi, nevrednicii robii Tăi, cântarea Sfintei Treimi și ne dăruiește ca în toți anii vieții noastre și în tot ceasul Ție slavă să-Ți înălțăm: Tatălui și Fiului și Sfântului Duh, acum și pururea și în vecii vecilor. Amin."),
        new Prayer("St Basil the Great, morning prayer", "Almighty Lord, the God of hosts and of all flesh, Thou livest in the heights, yet lookest down on the humble, proving the hearts and emotions, clearly foreknowing the secrets of men. Thou art the Light without beginning, in Whom there is no variation nor shadow of change. O Immortal King, accept the prayers which we now offer Thee from defiled lips. Free us from the sins we have committed in deed, word or thought, knowingly and unknowingly. Cleanse us from all defilement of flesh and spirit. Grant us to pass through the entire night of this present life with a watchful heart and a sober mind, awaiting the coming of the bright and manifest day of Thine only-begotten Son, our Lord, God and Savior Jesus Christ, when the Judge of all will come with glory to reward each according to his deeds. May we not be found fallen and lazy, but alert and roused to action, prepared to enter into His joy and the divine chamber of His glory, where the voice of those who feast is unceasing and indescribable is the delight of those who behold the inexpressible beauty of Thy countenance. For Thou art the true Light which enlightens and sanctifies all, and all creation hymns Thee unto ages of ages. Amen.",
                   "Rugăciunea a șasea a dimineții", "Doamne, Atotțiitorule, Dumnezeul puterilor și al tuturor trupurilor, Care între cele de sus locuiești și spre cele de jos privești; Cel Care ispitești inimile și rărunchii și tainele oamenilor le știi cu adevărat; Lumină fără de început și pururea fiitoare, în care nu este mutare sau umbră de schimbare; Însuți, Împărate fără de moarte, primește rugăciunile noastre pe care le aducem Ție din gurile noastre cele întinate, în acest ceas al nopții, îndrăznind pentru mulțimea milelor Tale. Iartă-ne greșelile ce am greșit înaintea Ta, cu cuvântul, cu fapta, din știință și din neștiință. Curățește-ne pe noi de toate întinăciunile trupești și sufletești, făcându-ne pe noi casă cinstitului și Sfântului Tău Duh. Și ne dăruiește nouă cu inimă veghetoare și curată să trecem toată noaptea acestei vieți, așteptând luminata și sfânta zi a Unuia-Născut Fiului Tău, a Domnului Dumnezeului și Mântuitorului nostru Iisus Hristos, când va veni pe pământ cu slavă să judece pe toți și să plătească fiecăruia după faptele lui. Ca să nu fim aflați zăcând și dormitând, ci priveghind și sculați în lucrarea poruncilor Lui și să fim gata a intra în bucuria și cămara slavei Lui celei dumnezeiești, unde este glasul cel neîncetat al celor care Te laudă și nespusa dulceață a celor care văd pururea frumusețea cea nespusă a slavei Tale. Că Tu ești Lumina cea adevărată, Care luminezi și sfințești toate, și pe Tine Te laudă toată făptura în veci. Amin."),
        new Prayer("St Basil the Great, morning prayer", "We bless Thee, most high God and Lord of mercies, Who ever doest great and unfathomable things for us — glorious and awesome things without number. Thou givest us sleep for the repose of our frailty, relieving the labors of our over-burdened flesh. We thank Thee for not destroying us in our lawlessness. Instead, Thou hast shown Thy usual love for mankind, and raised us, as we lay in despair, to glorify Thy Reign. Therefore, we implore Thy boundless goodness: enlighten our thoughts and eyes, and awaken our minds from the heavy sleep of laziness. Open our lips and fill them with Thy praise, that we may unwaveringly hymn and confess Thee, the God glorified in all and by all, Father without beginning, with Thine only-begotten Son and Thine all-holy, and life-giving Spirit, now and ever and unto ages of ages. Amen.",
                   "Rugăciunea a șaptea a dimineții", "Pe Tine Te binecuvântăm, Dumnezeule Preaînalte și Doamne al milelor, Cel Care faci cu noi pururea lucruri mari și cu anevoie de urmat, slăvite și preaminunate, care nu au număr. Cel Care ne-ai dat nouă somn spre odihna neputințelor noastre și spre repaos de ostenelile trupului, mulțumindu-Ți că nu ne-ai pierdut pe noi cu fărădelegile noastre, ci, după obicei, Te-ai arătat iubitor de oameni și ne-ai ridicat pe noi pentru a slăvi stăpânirea Ta. Pentru aceea ne rugăm bunătății Tale celei neasemănate: luminează ochii gândului nostru și ridică mintea noastră din somnul cel greu al lenei și deschide gura noastră și o umple de laudele Tale, ca să putem în liniște a cânta, a striga și a ne mărturisi pururea Ție, Dumnezeului Celui slăvit în toate și de toți: Tatălui Celui fără de început, împreună și Unuia-Născut Fiului Tău și Preasfântului și Bunului și de viață Făcătorului Tău Duh, acum și pururea și în vecii vecilor. Amin."),
        new Prayer("To the Most Holy Theotokos", "O Most Holy Theotokos, my Lady: through your holy and all-powerful prayers, turn away from me, your humble and unworthy servant, despair, forgetfulness, unreasonableness, indifference, and all unclean, evil and blasphemous thoughts from my wretched heart and darkened mind. Extinguish the flame of my passions, for I am poor and wretched. Deliver me from my numerous and wicked memories and fantasies. Free me from all evil acts, for you are blessed by all generations, and your most honorable name is glorified unto ages of ages. Amen.",
                   "Către Preasfânta Născătoare de Dumnezeu", "Preasfântă Stăpâna mea, de Dumnezeu Născătoare, cu sfintele și preaputernicele tale rugăciuni izgonește de la mine, smeritul și ticălosul robul tău, deznădăjduirea, uitarea, necunoștința, nepurtarea de grijă și toate gândurile cele întinate, cele rele și hulitoare de la ticăloasa mea inimă și de la întunecata mea minte. Și stinge văpaia poftelor mele, că sărac sunt și ticălos. Și mă izbăvește de multe rele și aduceri-aminte și năravuri, și de toate faptele cele rele mă slobozește. Că binecuvântată ești de toate neamurile și preacinstitul tău nume se slăvește în vecii vecilor. Amin."),
        new Prayer("To the Theotokos", "It is truly meet to bless you, O Theotokos, ever-blessed and most pure, and the Mother of our God. More honorable than the Cherubim, and more glorious beyond compare than the Seraphim: without defilement you gave birth to God the Word: true Theotokos, we magnify you.",
                   "Cuvine-se cu adevărat", "Cuvine-se cu adevărat să te fericim, Născătoare de Dumnezeu, cea pururea fericită și preanevinovată și Maica Dumnezeului nostru. Ceea ce ești mai cinstită decât heruvimii și mai mărită, fără de asemănare, decât serafimii, care fără stricăciune pe Dumnezeu Cuvântul ai născut, pe tine, cea cu adevărat Născătoare de Dumnezeu, te mărim."),
        new Prayer("St John Chrysostom, prayer 1 of 24", "Lord, exclude me not from Thy heavenly blessings.",
                   "Sfântul Ioan Gură de Aur, rugăciunea 1 din 24", "Doamne, nu mă lipsi de binele Tău cel ceresc."),
        new Prayer("St John Chrysostom, prayer 2 of 24", "Lord, deliver me from eternal torments.",
                   "Sfântul Ioan Gură de Aur, rugăciunea 2 din 24", "Doamne, izbăvește-mă de chinurile cele veșnice."),
        new Prayer("St John Chrysostom, prayer 3 of 24", "Lord, whether I have sinned in mind or thought, word or deed, forgive me.",
                   "Sfântul Ioan Gură de Aur, rugăciunea 3 din 24", "Doamne, de am greșit, fie cu mintea, fie cu gândul, sau cu cuvântul, sau cu fapta, iartă-mă."),
        new Prayer("St John Chrysostom, prayer 4 of 24", "Lord, deliver me from all ignorance, forgetfulness, cowardice, and stone-like insensitivity.",
                   "Sfântul Ioan Gură de Aur, rugăciunea 4 din 24", "Doamne, izbăvește-mă de toată neștiința și uitarea, de trândăvia și de nesimțirea cea împietrită."),
        new Prayer("St John Chrysostom, prayer 5 of 24", "Lord, deliver me from every temptation.",
                   "Sfântul Ioan Gură de Aur, rugăciunea 5 din 24", "Doamne, izbăvește-mă de toată ispitirea."),
        new Prayer("St John Chrysostom, prayer 6 of 24", "Lord, enlighten my heart which evil desires have darkened.",
                   "Sfântul Ioan Gură de Aur, rugăciunea 6 din 24", "Doamne, luminează-mi inima pe care a întunecat-o pofta cea rea."),
        new Prayer("St John Chrysostom, prayer 7 of 24", "Lord, as a man I have sinned: as a gracious God, have mercy on me, seeing the weakness of my soul.",
                   "Sfântul Ioan Gură de Aur, rugăciunea 7 din 24", "Doamne, eu ca un om am greșit, iar Tu ca un Dumnezeu îndurător, văzând neputința sufletului meu, miluiește-mă."),
        new Prayer("St John Chrysostom, prayer 8 of 24", "Lord, send Thy Grace to my aid, that I may glorify Thy holy name.",
                   "Sfântul Ioan Gură de Aur, rugăciunea 8 din 24", "Doamne, trimite mila Ta întru ajutorul meu, ca să preaslăvesc Preasfânt numele Tău."),
        new Prayer("St John Chrysostom, prayer 9 of 24", "Lord Jesus Christ, inscribe me, Thy servant, in the book of life, and grant me a good end.",
                   "Sfântul Ioan Gură de Aur, rugăciunea 9 din 24", "Doamne, Iisuse Hristoase, scrie-mă pe mine, robul Tău, în Cartea Vieții și-mi dăruiește sfârșit bun."),
        new Prayer("St John Chrysostom, prayer 10 of 24", "Lord, my God, even though I have done nothing good before Thee, grant by Thy Grace that I may make a good beginning.",
                   "Sfântul Ioan Gură de Aur, rugăciunea 10 din 24", "Doamne, Dumnezeul meu, deși n-am făcut nici un bine înaintea Ta, dă-mi, după harul Tău, să pun început bun."),
        new Prayer("St John Chrysostom, prayer 11 of 24", "Lord, sprinkle the dew of Thy Grace into my heart.",
                   "Sfântul Ioan Gură de Aur, rugăciunea 11 din 24", "Doamne, stropește inima mea cu roua harului Tău."),
        new Prayer("St John Chrysostom, prayer 12 of 24", "Lord of Heaven and earth, remember me, Thy sinful, shameful and impure servant, in Thy Kingdom. Amen.",
                   "Sfântul Ioan Gură de Aur, rugăciunea 12 din 24", "Doamne al cerului și al pământului, pomenește-mă pe mine, păcătosul, rușinatul și nevrednicul robul Tău, întru Împărăția Ta. Amin."),
        new Prayer("St John Chrysostom, prayer 13 of 24", "Lord, accept me in penitence.",
                   "Sfântul Ioan Gură de Aur, rugăciunea 13 din 24", "Doamne, primește-mă întru pocăință."),
        new Prayer("St John Chrysostom, prayer 14 of 24", "Lord, abandon me not.",
                   "Sfântul Ioan Gură de Aur, rugăciunea 14 din 24", "Doamne, nu mă lăsa."),
        new Prayer("St John Chrysostom, prayer 15 of 24", "Lord, lead me not into temptation.",
                   "Sfântul Ioan Gură de Aur, rugăciunea 15 din 24", "Doamne, nu mă duce în ispită."),
        new Prayer("St John Chrysostom, prayer 16 of 24", "Lord, grant me good thoughts.",
                   "Sfântul Ioan Gură de Aur, rugăciunea 16 din 24", "Doamne, dă-mi cuget bun."),
        new Prayer("St John Chrysostom, prayer 17 of 24", "Lord, grant me tears, the remembrance of death and compunction.",
                   "Sfântul Ioan Gură de Aur, rugăciunea 17 din 24", "Doamne, dă-mi lacrimi și aducere aminte de moarte și umilință."),
        new Prayer("St John Chrysostom, prayer 18 of 24", "Lord, grant me the thought of confessing my sins.",
                   "Sfântul Ioan Gură de Aur, rugăciunea 18 din 24", "Doamne, dă-mi cuget să mărturisesc toate păcatele mele."),
        new Prayer("St John Chrysostom, prayer 19 of 24", "Lord, grant me humility, chastity and obedience.",
                   "Sfântul Ioan Gură de Aur, rugăciunea 19 din 24", "Doamne, dă-mi smerenie, curăție și ascultare."),
        new Prayer("St John Chrysostom, prayer 20 of 24", "Lord, grant me patience, courage and meekness.",
                   "Sfântul Ioan Gură de Aur, rugăciunea 20 din 24", "Doamne, dă-mi răbdare și voie nebiruită și blândețe."),
        new Prayer("St John Chrysostom, prayer 21 of 24", "Lord, cause the root of good to dwell in me — Thy fear in my heart.",
                   "Sfântul Ioan Gură de Aur, rugăciunea 21 din 24", "Doamne, sădește în mine rădăcina bunătăților și frica Ta în inima mea."),
        new Prayer("St John Chrysostom, prayer 22 of 24", "Lord, grant that I may love Thee with all my soul and mind and to do Thy will in all things.",
                   "Sfântul Ioan Gură de Aur, rugăciunea 22 din 24", "Doamne, învrednicește-mă să Te iubesc cu tot sufletul și gândul meu și să fac în toate voia Ta."),
        new Prayer("St John Chrysostom, prayer 23 of 24", "Lord, protect me from certain people, demons and passions, and from any other unseemly thing.",
                   "Sfântul Ioan Gură de Aur, rugăciunea 23 din 24", "Doamne, apără-mă de oamenii gâlcevitori, de diavoli și de patimile trupești și de toate celelalte lucruri necuviincioase."),
        new Prayer("St John Chrysostom, prayer 24 of 24", "Lord, I know that Thou doest as Thou wilt: may Thy will be in me, a sinner, for blessed art Thou for ever. Amen.",
                   "Sfântul Ioan Gură de Aur, rugăciunea 24 din 24", "Doamne, știu că faci precum vrei Tu, deci să fie și întru mine, păcătosul, voia Ta, că binecuvântat ești în veci. Amin."),
        new Prayer("Evening troparion", "Have mercy on us, O Lord, have mercy on us, for laying aside all excuse, we sinners offer to Thee, as to our Master, this supplication: have mercy on us.",
                   "Troparul de umilință", "Miluiește-ne pe noi, Doamne, miluiește-ne pe noi, că, nepricepându-ne de nici un răspuns, această rugăciune aducem Ție, ca unui Stăpân, noi păcătoșii robii Tăi; miluiește-ne pe noi."),
        new Prayer("Evening troparion", "O Lord, have mercy on us, for in Thee have we put our trust. Do not be angry with us, nor remember our iniquities, but look down on us even now, since Thou art compassionate, and deliver us from our enemies; for Thou art our God and we are Thy people; we are all the work of Thy hands, and we call on Thy name.",
                   "Troparul de umilință", "Doamne, miluiește-ne pe noi, că întru Tine am nădăjduit; nu Te mânia pe noi foarte, nici pomeni fărădelegile noastre, ci caută și acum ca un milostiv și ne izbăvește pe noi de vrăjmașii noștri, că Tu ești Dumnezeul nostru și noi suntem poporul Tău, toți lucrul mâinilor Tale și numele Tău chemăm."),
        new Prayer("Evening troparion to the Theotokos", "O blessed Theotokos, open the doors of compassion to us whose hope is in you, that we may not perish but be delivered from adversity through you, who are the salvation of the Christian people.",
                   "Troparul Născătoarei de Dumnezeu", "Ușa milostivirii deschide-o nouă, binecuvântată Născătoare de Dumnezeu, ca să nu pierim cei ce nădăjduim întru tine, ci să ne mântuim prin tine din nevoi, că tu ești mântuirea neamului creștinesc."),
        new Prayer("St Macarius the Great, evening prayer to God the Father", "O Eternal God and King of all Creation, Who hast granted me to reach this hour: forgive the sins I have committed this day in deed, word and thought. Cleanse, O Lord, my humble soul from every defilement of flesh and spirit. Grant, Lord, that I may pass through this night in peace. When I rise from my humble bed, may I please Thy most holy Name all the days of my life and trample under foot the physical and bodiless enemies that wage war against me. Deliver me, Lord, from vain thoughts which defile me and from evil lusts. For Thine is the Kingdom and the Power and the Glory, of the Father, and of the Son, and of the Holy Spirit, now and ever and unto ages of ages. Amen.",
                   "Sfântul Macarie cel Mare, către Dumnezeu Tatăl", "Dumnezeule cel veșnic și Împărate a toată făptura, Cel ce m-ai învrednicit a ajunge până în acest ceas, iartă-mi păcatele ce am făcut în această zi, cu fapta, cu cuvântul și cu gândul; și curățește, Doamne, smeritul meu suflet de toată întinăciunea trupului și a sufletului. Și-mi dă, Doamne, în această noapte, a trece somnul în pace ca, sculându-mă din ticălosul meu așternut, bine să plac Preasfântului Tău nume în toate zilele vieții mele și să calc pe vrăjmașii cei ce se luptă cu mine, pe cei trupești și pe cei fără de trup. Și mă izbăvește, Doamne, de gândurile cele deșarte, care mă întinează, și de poftele cele rele. Că a Ta este împărăția, puterea și slava, a Tatălui și a Fiului și a Sfântului Duh, acum și pururea și în vecii vecilor. Amin."),
        new Prayer("St Antiochus, evening prayer to our Lord Jesus Christ", "Almighty Word of the Father, Jesus Christ, Who art perfect: never abandon me, Thy servant, for Thy great mercy's sake, but ever abide in me. O Jesus, Good Shepherd of Thy sheep, do not deliver me to the serpent's rebellion! Do not abandon me to Satan's will, for the seed of corruption is within me! Instead, O Lord God the Adored, Holy King Jesus Christ, keep me while I sleep by Thy unwavering Light, Thy Holy Spirit by Whom Thou didst sanctify Thy disciples. O Lord, grant to me, Thine unworthy servant, salvation on my bed. Enlighten my mind with the light of understanding Thy Holy Gospel; my soul with the love of Thy Cross; my heart with the purity of Thy Word; my body with Thy passionless Passion. Keep my thoughts with Thy humility and raise me at the right time to glorify Thee. For Thou art most glorified, with Thine unoriginate Father and Thy most Holy Spirit forever. Amen.",
                   "Sfântul Antioh, către Domnul nostru Iisus Hristos", "Atotțiitorule, Cuvinte al Tatălui, Însuți fiind desăvârșit, Iisuse Hristoase, pentru multă milostivirea Ta, nu Te dezlipi de mine, robul Tău, ci odihnește întru mine pururea, Iisuse, Cel ce ești Păstor bun al oilor Tale. Nu mă da ispitei șarpelui, nici nu mă lăsa în pofta satanei, că sămânța stricăciunii este întru mine. Tu, Doamne Dumnezeule, Cel Căruia ne închinăm, Împărate Sfinte, Iisuse Hristoase, păzește-mă în timpul somnului cu lumina cea neîntunecată, cu Duhul Tău cel Sfânt, cu Care ai sfințit pe ucenicii Tăi. Dă-mi, Doamne, și mie, nevrednicului robului Tău, mântuirea Ta în așternutul meu. Luminează mintea mea cu lumina înțelegerii Sfintei Tale Evanghelii, sufletul meu cu dragostea Crucii Tale, inima mea cu curăția cuvintelor Tale, trupul meu cu patima Ta cea nebiruită, cugetul meu cu smerenia Ta îl păzește și mă ridică la vreme cuviincioasă spre a Ta slăvire, că preaslăvit ești cu Cel fără de început al Tău Părinte și cu Preasfântul Duh în veci. Amin."),
        new Prayer("Evening prayer to the Holy Spirit", "O Lord, the Heavenly King, the Comforter, the Spirit of Truth: have compassion and mercy on me, Thy sinful servant! Absolve me, who am unworthy. Forgive all the sins I have committed this day both in my humanity and my inhumanity, behaving worse than beasts in sins voluntary and involuntary, known and unknown, from my youth, from evil suggestions, haste and despondency. If I have sworn by Thy name or blasphemed it in thought; if I have reproached anyone or become angered by something; or slandered or saddened anyone in my anger; or have lied, or slept unnecessarily; or a beggar has come to me and I have despised him; or have saddened my brother or quarrelled with him; or have judged someone; or have allowed myself to become haughty, proud or angry; or, when standing in prayer, my mind has been shaken by the wickedness of this world; or have entertained depraved thoughts; or have over-eaten, over-drunk or laughed mindlessly; or have had evil thoughts or seen the beauty of someone and been wounded by it in my heart; or have spoken inappropriately; or have laughed at my brother's sins when my own transgressions are countless; or have been indifferent to prayer; or have done any other evil that I can not remember — for I have done all this and more: have mercy, O Master, my Creator, on me, Thy despondent and unworthy servant! Absolve, remit and forgive me, in Thy goodness and love for mankind, that I, who am prodigal, sinful and wretched, may lie down in peace and find sleep and rest. May I worship, hymn and praise Thy most honorable Name, with the Father and His only-begotten Son, now and ever and unto ages of ages. Amen.",
                   "Către Sfântul Duh, seara", "Doamne, Împărate Ceresc, Mângâietorule, Duhule adevărate, milostivește-Te spre mine, păcătosul robul Tău, și mă miluiește și-mi iartă mie, nevrednicului, toate câte am greșit Ție astăzi ca un om, și nu numai ca un om, ci și mai rău decât necuvântătoarele, păcatele mele cele de voie și cele fără de voie, cele știute și cele neștiute, care sunt din tinerețe și din obiceiul cel rău și care sunt din voia cea slobodă și din lene; ori de m-am jurat cu numele Tău, ori de L-am hulit în gândul meu, sau pe cineva am ocărât, sau pe cineva am clevetit în mânia mea, sau am mâhnit, sau de ceva m-am mâniat, sau am mințit, sau fără de vreme am dormit, sau vreun sărac a venit la mine și nu l-am socotit, sau pe fratele meu l-am mâhnit, sau m-am sfădit, sau pe cineva am osândit, sau m-am mărit, sau m-am trufit, sau m-am mâniat, sau, stând la rugăciune, mintea mea s-a îngrijit de vicleniile acestei lumi, sau răzvrătire am cugetat, sau prea m-am săturat, sau m-am îmbătat, sau nebunește am râs, sau ceva rău am cugetat, sau frumusețe străină am văzut și cu dânsa mi-am rănit inima, sau ce nu se cuvine am grăit, sau de păcatul fratelui meu am râs, iar păcatele mele sunt nenumărate, sau de rugăciune nu m-am îngrijit, sau altceva rău am făcut și nu-mi aduc aminte; că acestea toate și mai mari decât acestea am făcut. Miluiește-mă, Stăpâne și Făcătorul meu, pe mine leneșul și nevrednicul robul Tău, și mă ușurează, și mă slobozește și mă iartă, ca un bun și de oameni iubitor. Ca în pace să mă culc și să dorm eu, păcătosul și necuratul și ticălosul, și să mă închin și să cânt și să preaslăvesc preacinstitul Tău nume, împreună cu al Tatălui și cu al Unuia-Născut Fiului Lui, acum și pururea și în vecii vecilor. Amin."),
        new Prayer("Evening prayer", "O Lord our God, forgive all the sins I have committed this day in word, deed and thought, for Thou art good and lovest mankind. Grant me a peaceful sleep, free of restlessness. Send Thy Guardian Angel to protect and keep me from all harm. For Thou art the Guardian of our souls and bodies, and to Thee we ascribe glory, to the Father, and to the Son, and to the Holy Spirit, now and ever and unto ages of ages. Amen.",
                   "Rugăciunea a patra a serii", "Doamne, Dumnezeul nostru, orice am greșit în această zi cu cuvântul, cu fapta, și cu gândul, ca un bun și iubitor de oameni, iartă-mi. Somn cu pace și fără mâhnire dăruiește-mi. Pe îngerul Tău cel apărător trimite-l să mă acopere și să mă păzească de tot răul. Că Tu ești păzitorul sufletelor și al trupurilor noastre și Ție slavă înălțăm, Tatălui și Fiului și Sfântului Duh, acum și pururea și în vecii vecilor. Amin."),
        new Prayer("Evening prayer", "O Lord our God, in Whom we believe and upon Whose Name we call more than any other name: grant relief to our souls and bodies as we go to sleep. Keep us from every fantasy and dark pleasure. Halt the rushing of passions and quench the fiery arousals of the flesh. Grant us to live chastely in word and deed. Having embraced a virtuous life, may we not fall away from Thy promised blessings, for blessed art Thou for ever. Amen.",
                   "Rugăciunea a cincea a serii", "Doamne, Dumnezeul nostru, în Care credem și al Cărui nume mai mult decât tot numele Îl chemăm, dă-ne nouă iertare sufletului și trupului, celor ce mergem spre somn; păzește-ne de toată nălucirea și, fără întunecată dulceață, potolește pornirea poftelor, stinge aprinderea zburdării trupești și ne dă în curăție a viețui cu lucrurile și cuvintele, ca, dobândind viață cu fapte bune, să nu cădem din binele Tău cel făgăduit, că binecuvântat ești în veci. Amin."),
        new Prayer("Evening prayer to the Most Holy Theotokos", "O Good Mother of the Good King, most pure and blessed Mary the Theotokos: pour out the mercy of your Son and our God on my passionate soul. Direct me towards good deeds through your prayers, that I may pass through the remainder of my life without stain, and find Paradise through you, O Virgin Theotokos who alone are pure and blessed.",
                   "Către Sfânta Născătoare de Dumnezeu, seara", "Preacurată și binecuvântată de Dumnezeu Născătoare, Marie, Maica cea bună a Bunului Împărat, varsă mila Fiului Tău și Dumnezeului nostru spre pătimașul meu suflet și, cu rugăciunile tale, mă îndreptează spre fapte bune, ca cealaltă vreme a vieții mele fără de prihană să o trec și pentru tine raiul să dobândesc, Fecioară de Dumnezeu Născătoare, care ești una curată și binecuvântată."),
        new Prayer("To the Holy Guardian Angel", "Angel of Christ, my holy guardian, the protector of my soul and body: forgive me for all the sins I have committed this day. Deliver me from all the evil of my militant Enemy, that I may not anger my God by any sin. Pray for me, your sinful and unworthy servant, that you may show me worthy of the goodness and mercy of the All-Holy Trinity, the Mother of my Lord Jesus Christ and all the Saints. Amen.",
                   "Către sfântul înger păzitor", "Îngerule al lui Hristos, păzitorul meu cel sfânt și acoperitorul sufletului și al trupului meu, iartă-mi toate câte am greșit în ziua de astăzi, și de toată viclenia vrăjmașului meu celui potrivnic mă izbăvește, ca să nu mânii cu niciun păcat pe Dumnezeul meu; și te roagă pentru mine, păcătosul și nevrednicul rob, ca să mă arăți vrednic bunătății și milei Preasfintei Treimi și Maicii Domnului meu Iisus Hristos și tuturor sfinților. Amin"),
        new Prayer("Kontakion to the Theotokos", "O victorious leader of triumphant hosts! We your servants, delivered from evil, sing our grateful thanks to you, O Theotokos! As you possess invincible might, set us free from every calamity so that we may sing: Rejoice, O unwedded Bride!",
                   "Condacul Născătoarei de Dumnezeu", "Apărătoare Doamnă, pentru biruință mulțumiri, izbăvindu-ne din nevoi, aducem ție, Născătoare de Dumnezeu, noi, robii tăi. Ci, ca aceea ce ai stăpânire nebiruită, izbăvește-ne din toate nevoile, ca să strigăm ție: Bucură-te, Mireasă, pururea fecioară."),
        new Prayer("To the Ever-Virgin", "Most glorious Ever-Virgin Mother of Christ our God, bear our prayer to your Son and our God, that through you He may save our souls.",
                   "Către Pururea Fecioara", "Fecioară, care ești pururea slăvită, de Dumnezeu Născătoare, Marie, Maica lui Hristos, Dumnezeul nostru, primește rugăciunile noastre și le du Fiului tău și Dumnezeului nostru, ca să mântuiască și să lumineze, pentru tine, sufletele noastre."),
        new Prayer("To the Mother of God", "All my hope I place in you, O Mother of God: keep me under your protection!",
                   "Către Maica lui Dumnezeu", "Toată nădejdea mea spre tine o pun, Maica lui Dumnezeu, păzește-mă sub acoperământul tău."),
        new Prayer("To the Virgin Theotokos", "Virgin Theotokos, do not despise me a sinner who craves your help and intercession. My soul hopes in you, have mercy on me!",
                   "Către Fecioara Născătoare de Dumnezeu", "De Dumnezeu Născătoare Fecioară, nu mă trece cu vederea pe mine, păcătosul, cel ce am nevoie de ajutorul tău și de folosința ta, că spre tine nădăjduiește sufletul meu, și mă miluiește."),
        new Prayer("Prayer of St Ioannikios", "My Hope is the Father; my Refuge is the Son; my Protection is the Holy Spirit: O Holy Trinity, glory to Thee!",
                   "Rugăciunea Sfântului Ioanichie", "Nădejdea mea este Tatăl, scăparea mea este Fiul, acoperământul meu este Duhul Sfânt, Treime Sfântă, slavă Ție."),
        new Prayer("Through the prayers of the saints", "Lord Jesus Christ, Son of God, for the sake of the prayers of Thy most pure Mother, our venerable and God-bearing fathers and all the saints, save me, a sinner. Amen.",
                   "Pentru rugăciunile sfinților", "Doamne, Iisuse Hristoase, Fiul lui Dumnezeu, pentru rugăciunile Preacuratei Maicii Tale, ale cuvioșilor părinților noștri și ale tuturor sfinților, mântuiește-mă pe mine, păcătosul."),
        new Prayer("Prayer of St John of Damascus", "O Master Who lovest mankind, is this bed to be my coffin? Or wilt Thou enlighten my wretched soul with another day? Behold: before me lies the coffin, before me stands death! O Lord, I fear Thy judgment and the endless torments, yet I cease not to do evil. I always anger Thee, my Lord God, and Thy most pure Mother, all the heavenly hosts and my holy Guardian Angel. I know, Lord, that I am unworthy of Thy love for mankind. Indeed, I am worthy of every condemnation and torment. Yet, Lord, save me whether I want it or not! When Thou savest the righteous, it is no great thing. When Thou hast mercy on the pure, it causes no wonder, for they are worthy of Thy mercy. Astound us with Thy mercy towards me, a sinner. Reveal in this manner Thy love for mankind, that my wickedness may not overcome Thine inexpressible goodness and mercy. As Thou wilt, order my life!",
                   "Rugăciunea Sfântului Ioan Damaschin", "Stăpâne, Iubitorule de oameni, au doară nu-mi va fi mie acest pat groapă? Sau încă vei mai lumina cu ziua ticălosul meu suflet? Iată, groapa îmi zace înainte și iată, moartea îmi stă înainte. De judecata Ta, Doamne, mă tem, și de chinul cel fără de sfârșit; iar a face rău nu mai contenesc. Pe Tine, Domnul Dumnezeul meu, pururea Te mânii și pe Preacurata Maica Ta și pe toate puterile cerești și pe sfântul înger, păzitorul meu. Și știu, Doamne, că nu sunt vrednic de iubirea Ta de oameni, ci vrednic sunt de toată osânda și chinul. Ci, rogu-Te, Doamne, mântuiește-mă după mulțimea bunătății Tale, că, de vei mântui pe cel drept, nu-i lucru mare, iar de vei milui pe cel curat, nu-i nicio minune, că sunt vrednici de mila Ta, ci spre mine, păcătosul, să faci minuni cu mila Ta; întru aceasta să arăți iubirea Ta de oameni, ca să nu biruiască răutatea mea bunătatea și milostivirea Ta cea veșnică, ci, precum voiești, tocmește pentru mine lucrul."),
        new Prayer("Before sleep", "Enlighten my eyes, Christ — God, that I fall not asleep to death and that my enemy may not say of me: I have overcome him.",
                   "Înainte de somn", "Luminează ochii mei, Hristoase Dumnezeule, ca nu cândva să adorm întru moarte, ca nu cândva să zică vrăjmașul meu: întăritu-m-am asupra lui."),
        new Prayer("Before sleep", "Be the Helper of my soul, O God, for I walk among many snares. Deliver me from them, O Good One, and save me, for Thou lovest mankind.",
                   "Înainte de somn", "Sprijinitor sufletului meu fii, Dumnezeule, că umblu prin mijlocul a multe curse; izbăvește-mă de dânsele și mă mântuiește, Bunule, ca un iubitor de oameni."),
        new Prayer("To the Mother of God, before sleep", "Let us ever hymn the most glorious Mother of God, who is holier than the Holy Angels. With heart and lips let us confess that she is the Theotokos, for she truly bore God incarnate for us and prays ceaselessly for our souls.",
                   "Către Maica Domnului, înainte de somn", "Preaslăvită Maică a lui Dumnezeu, care ești mai sfântă decât sfinții îngeri, neîncetat te cântăm cu inima și cu gura, mărturisind că tu ești de Dumnezeu Născătoare, căci cu adevărat ne-ai născut nouă pe Dumnezeu întrupat și te rogi neîncetat pentru sufletele noastre."),
        new Prayer("Prayer to the Precious Cross", "Let God arise and let His enemies be scattered! Let those who hate Him flee from before His face! As smoke vanishes, so let them vanish. As wax melts before the fire, so let sinners perish before the face of those who love God and sign themselves with the Sign of the Cross and say joyfully: rejoice, most precious and life-creating Cross of the Lord, which chases demons away through the power of our Lord Jesus Christ Who was nailed to you, descended into hell and, having trampled down the power of the devil, gave to us His precious Cross for the routing of all enemies. Help me for ever, most precious and life-creating Cross of the Lord, with the Holy Lady Virgin Theotokos and all the Saints. Amen.",
                   "Rugăciunea cinstitei Cruci", "Să învie Dumnezeu și să se risipească vrăjmașii Lui și să fugă de la fața Lui cei ce-L urăsc pe Dânsul. Să piară cum piere fumul; cum se topește ceara de fața focului, așa să piară diavolii de la fața celor ce iubesc pe Dumnezeu și se însemnează cu semnul Crucii și zic cu veselie: Bucură-te, preacinstită și de viață făcătoare Crucea Domnului, care alungi pe diavoli cu puterea Celui ce S-a răstignit pe tine, a Domnului nostru Iisus Hristos, și S-a pogorât la iad și a călcat puterea diavolului și te-a dăruit nouă pe tine, cinstită Crucea Sa, spre alungarea a tot pizmașul. O, preacinstită și de viață făcătoare Crucea Domnului, ajută-mi cu Sfânta Doamnă Fecioară, Născătoare de Dumnezeu, și cu toți sfinții în veci. Amin."),
        new Prayer("Prayer of St Ephraim the Syrian", "O Lord and Master of my life! Take from me the spirit of sloth, despair, lust of power and idle talk.\nBut give rather the spirit of chastity, humility, patience, and love to Thy servant.\nYea, O Lord and King! Grant me to see my own transgressions and not to judge my brother, for blessed art Thou, unto ages of ages.",
                   "Rugăciunea Sfântului Efrem Sirul", "Doamne și Stăpânul vieții mele, duhul trândăviei, al grijii de multe, al iubirii de stăpânire și al grăirii în deșert nu mi-l da mie.\nIar duhul curăției, al gândului smerit, al răbdării și al dragostei, dăruiește-l mie, robului Tău.\nAșa Doamne, Împărate, dăruiește-mi ca să-mi văd greșalele mele și să nu osândesc pe fratele meu, că binecuvântat ești în vecii vecilor. Amin."),
        new Prayer("A short prayer", "O God, cleanse me a sinner. (12 times)",
                   "Rugăciune scurtă", "Dumnezeule, curățește-mă pe mine păcătosul."),
        new Prayer("Blessing of the table", "O Christ God, bless the food and drink of Thy servants, for Thou art holy, always, now and ever and unto ages of ages. Amen.",
                   "Rugăciunea mesei", "Hristoase Dumnezeule, binecuvintează mâncarea și băutura robilor Tăi, că sfânt ești totdeauna, acum și pururea și în vecii vecilor. Amin."),
        new Prayer("Thanksgiving after the meal", "We thank Thee, Christ our God, for Thou hast satisfied us with Thine earthly gifts. Deprive us not of Thy Heavenly Kingdom, but as Thou camest among Thy disciples, O Savior, giving them peace, so come to us and save us!",
                   "Mulțumire după masă", "Mulțumim Ție, Hristoase, Dumnezeul nostru, că ne-ai săturat pe noi de bunătățile Tale cele pământești; nu ne lipsi pe noi nici de cereasca Ta împărăție, ci, precum în mijlocul ucenicilor Tăi ai venit, Mântuitorule, pace dându-le lor, vino și la noi și ne mântuiește."),
        new Prayer("Psalm 144, verses 1-3", "I will exalt thee, my God, my king; and I will bless thy name for ever and ever.\nEvery day will I bless thee, and I will praise thy name for ever and ever.\nThe Lord is great, and greatly to be praised; and there is no end of his greatness.",
                   "Psalmul 144, versetele 1-3", "Înălța-Te-voi Dumnezeul meu, Împăratul meu și voi binecuvânta numele Tău în veac și în veacul veacului.\nÎn toate zilele Te voi binecuvânta și voi lăuda numele Tău în veac și în veacul veacului.\nMare este Domnul și lăudat foarte și măreția Lui nu are sfârșit."),
        new Prayer("Psalm 144, verses 8-9", "The Lord is compassionate, and merciful; long-suffering, and abundant in mercy.\nThe Lord is good to those that wait on him; and his compassions are over all his works.",
                   "Psalmul 144, versetele 8-9", "Îndurat și milostiv este Domnul, îndelung-răbdător și mult-milostiv.\nBun este Domnul cu toți și îndurările Lui peste toate lucrurile Lui."),
        new Prayer("Psalm 144, verses 14-16", "The Lord supports all that are falling, and sets up all that are broken down.\nThe eyes of all wait upon thee; and thou givest them their food in due season.\nThou openest thine hands, and fillest every living thing with pleasure.",
                   "Psalmul 144, versetele 14-16", "Domnul sprijină pe toți cei ce cad și îndreaptă pe toți cei gârboviți.\nOchii tuturor spre Tine nădăjduiesc și Tu le dai lor hrană la bună vreme.\nDeschizi Tu mâna Ta și de bunăvoință saturi pe toți cei vii."),
        new Prayer("Psalm 144, verses 18-19", "The Lord is near to all that call upon him, to all that call upon him in truth.\nHe will perform the desire of them that fear him: and he will hear their supplication, and save them.",
                   "Psalmul 144, versetele 18-19", "Aproape este Domnul de toți cei ce-L cheamă pe El, de toți cei ce-L cheamă pe El întru adevăr.\nVoia celor ce se tem de El o va face și rugăciunea lor o va auzi și-i va mântui pe dânșii."),
        new Prayer("Psalm 22, verses 1-3", "The Lord tends me as a shepherd, and I shall want nothing.\nIn a place of green grass, there he has made me dwell: he has nourished me by the water of rest.\nHe has restored my soul: he has guided me into the paths of righteousness, for his name's sake.",
                   "Psalmul 22, versetele 1-3", "Domnul mă paște și nimic nu-mi va lipsi.\nLa loc de pășune, acolo m-a sălășluit; la apa odihnei m-a hrănit.\nSufletul meu l-a întors, povățuitu-m-a pe căile dreptății, pentru numele Lui."),
        new Prayer("Psalm 22, verse 4", "Yea, even if I should walk in the midst of the shadow of death, I will not be afraid of evils: for thou art with me; thy rod and thy staff, these have comforted me.",
                   "Psalmul 22, versetul 4", "Că de voi și umbla în mijlocul morții, nu mă voi teme de rele; că Tu cu mine ești."),
        new Prayer("Psalm 90, verses 1-2", "He that dwells in the help of the Highest, shall sojourn under the shelter of the God of heaven.\nHe shall say to the Lord, Thou art my helper and my refuge: my God; I will hope in him.",
                   "Psalmul 90, versetele 1-2", "Cel ce locuiește în ajutorul Celui Preaînalt, întru acoperământul Dumnezeului cerului se va sălășlui.\nVa zice Domnului: \"Sprijinitorul meu ești și scăparea mea; Dumnezeul meu, voi nădăjdui spre Dânsul\"."),
        new Prayer("Psalm 90, verses 3-4", "For he shall deliver thee from the snare of the hunters, from every troublesome matter.\nHe shall overshadow thee with his shoulders, and thou shalt trust under his wings: his truth shall cover thee with a shield.",
                   "Psalmul 90, versetele 3-4", "Că El te va izbăvi din cursa vânătorilor și de cuvântul tulburător.\nCu spatele te va umbri pe tine și sub aripile Lui vei nădăjdui; ca o armă te va înconjura adevărul Lui."),
        new Prayer("Psalm 90, verses 5-6", "Thou shalt not be afraid of terror by night; nor of the arrow flying by day; nor of the evil thing that walks in darkness; nor of calamity, and the evil spirit at noon-day.",
                   "Psalmul 90, versetele 5-6", "Nu te vei teme de frica de noapte, de săgeata ce zboară ziua,\nDe lucrul ce umblă în întuneric, de molima ce bântuie întru amiază."),
        new Prayer("Psalm 90, verses 9-10", "For thou, O Lord, art my hope: thou, my soul, hast made the Most High thy refuge.\nNo evils shall come upon thee, and no scourge shall draw nigh to thy dwelling.",
                   "Psalmul 90, versetele 9-10", "Pentru că pe Domnul, nădejdea mea, pe Cel Preaînalt L-ai pus scăpare ție.\nNu vor veni către tine rele și bătaie nu se va apropia de locașul tău."),
        new Prayer("Psalm 90, verses 11-12", "For he shall give his angels charge concerning thee, to keep thee in all thy ways.\nThey shall bear thee up on their hands, lest at any time thou dash thy foot against a stone.",
                   "Psalmul 90, versetele 11-12", "Că îngerilor Săi va porunci pentru tine ca să te păzească în toate căile tale.\nPe mâini te vor înălța ca nu cumva să împiedici de piatră piciorul tău."),
        new Prayer("Psalm 26, verses 1-2", "The Lord is my light and my Saviour; whom shall I fear? the Lord is the defender of my life; of whom shall I be afraid?",
                   "Psalmul 26, versetele 1-2", "Domnul este luminarea mea și mântuirea mea; de cine mă voi teme?\nDomnul este apărătorul vieții mele; de cine mă voi înfricoșa?"),
        new Prayer("Psalm 120, verses 1-2", "I lifted up mine eyes to the mountains, whence my help shall come.\nMy help shall come from the Lord, who made the heaven and the earth.",
                   "Psalmul 120, versetele 1-2", "Ridicat-am ochii mei la munți, de unde va veni ajutorul meu.\nAjutorul meu de la Domnul, Cel ce a făcut cerul și pământul."),
        new Prayer("Psalm 120, verses 7-8", "May the Lord preserve thee from all evil: the Lord shall keep thy soul.\nThe Lord shall keep thy coming in, and thy going out, from henceforth and even for ever.",
                   "Psalmul 120, versetele 7-8", "Domnul te va păzi pe tine de tot răul; păzi-va sufletul tău.\nDomnul va păzi intrarea ta ieșirea ta de acum și până în veac."),
        new Prayer("Psalm 4, verse 1", "When I called upon him, the God of my righteousness heard me: thou hast made room for me in tribulation; pity me, and hearken to my prayer.",
                   "Psalmul 4, versetul 1", "Când Te-am chemat, m-ai auzit, Dumnezeul dreptății mele! Întru necaz m-ai desfătat! Milostivește-Te spre mine și ascultă rugăciunea mea."),
        new Prayer("Psalm 4, verse 8", "I will both lie down in peace and sleep: for thou, Lord, only hast caused me to dwell securely.",
                   "Psalmul 4, versetul 8", "Cu pace, așa mă voi culca și voi adormi, că Tu, Doamne, îndeosebi întru nădejde m-ai așezat."),
        new Prayer("Psalm 45, verses 1-2", "God is our refuge and strength, a help in the afflictions that have come heavily upon us.\nTherefore will we not fear when the earth is troubled, and the mountains are removed into the depths of the seas.",
                   "Psalmul 45, versetele 1-2", "Dumnezeu este scăparea și puterea noastră, ajutor întru necazurile ce ne împresoară.\nPentru aceasta nu ne vom teme când se va cutremura pământul și se vor muta munții în inima mărilor."),
        new Prayer("Psalm 50, verses 1-2", "Have mercy upon me, O God, according to thy great mercy; and according to the multitude of thy compassions blot out my transgression.",
                   "Psalmul 50, versetele 1-2", "Miluiește-mă, Dumnezeule, după mare mila Ta\nȘi după mulțimea îndurărilor Tale, șterge fărădelegea mea."),
        new Prayer("Psalm 50, verses 11-12", "Create in me a clean heart, O God; and renew a right spirit in my inward parts.\nCast me not away from thy presence; and remove not thy Holy Spirit from me.",
                   "Psalmul 50, versetele 11-12", "Inimă curată zidește intru mine, Dumnezeule și duh drept înnoiește întru cele dinlăuntru ale mele.\nNu mă lepăda de la fața Ta și Duhul Tău cel sfânt nu-l lua de la mine."),
        new Prayer("Psalm 138, verses 11-12", "When I said, Surely the darkness will cover me; even the night was light in my luxury.\nFor darkness will not be darkness with thee; but night will be light as day: as its darkness, so shall its light be to thee.",
                   "Psalmul 138, versetele 11-12", "Și am zis: \"Poate întunericul mă va acoperi și se va face noapte lumina dimprejurul meu\".\nDar întunericul nu este întuneric la Tine și noaptea ca ziua va lumina. Cum este întunericul ei, așa este și lumina ei."),
        new Prayer("Psalm 33, verses 1-2", "I will bless the Lord at all times: his praise shall be continually in my mouth.\nMy soul shall boast herself in the Lord: let the meek hear, and rejoice.",
                   "Psalmul 33, versetele 1-2", "Bine voi cuvânta pe Domnul în toată vremea, pururea lauda Lui în gura mea.\nÎn Domnul se va lăuda sufletul meu; să audă cei blânzi și să se veselească."),
        new Prayer("Psalm 33, verse 4", "I sought the Lord diligently, and he hearkened to me, and delivered me from all my sojournings.",
                   "Psalmul 33, versetul 4", "Căutat-am pe Domnul și m-a auzit și din toate necazurile mele m-a izbăvit."),
        new Prayer("Psalm 33, verse 17", "The Lord is near to them that are of a contrite heart; and will save the lowly in spirit.",
                   "Psalmul 33, versetul 17", "Aproape este Domnul de cei umiliți la inimă și pe cei smeriți cu duhul îi va mântui."),
        new Prayer("Psalm 17, verses 1-2", "I will love thee, O Lord, my strength.\nThe Lord is my firm support, and my refuge, and my deliverer; my God is my helper, I will hope in him; he is my defender, and the horn of my salvation, and my helper.",
                   "Psalmul 17, versetele 1-2", "Iubi-Te-voi Doamne, vârtutea mea. Domnul este întărirea mea și scăparea mea și izbăvitorul meu,\nDumnezeul meu, ajutorul meu și voi nădăjdui spre Dânsul,"),
        new Prayer("Psalm 30, verse 5", "Into thine hands I will commit my spirit: thou hast redeemed me, O Lord God of truth.",
                   "Psalmul 30, versetul 5", "În mâinile Tale îmi voi da duhul meu; izbăvitu-m-ai, Doamne, Dumnezeul adevărului."),
        new Prayer("Psalm 55, verse 3", "They shall be afraid, but I will trust in thee.",
                   "Psalmul 55, versetul 3", "Ziua când mă voi teme, voi nădăjdui în Tine."),
        new Prayer("Psalm 60, verses 1-2", "O God, hearken to my petition; attend to my prayer.\nFrom the ends of the earth have I cried to thee, when my heart was in trouble: thou liftedst me up on a rock, thou didst guide me:",
                   "Psalmul 60, versetele 1-2", "Auzi, Dumnezeule, cererea mea, ia aminte la rugăciunea mea!\nDe la marginile pământului către Tine am strigat; când s-a mâhnit inima mea, pe piatră m-ai înălțat."),
        new Prayer("Psalm 62, verses 1-3", "O God, my God, I cry to thee early; my soul has thirsted for thee: how often has my flesh longed after thee, in a barren and trackless and dry land!",
                   "Psalmul 62, versetele 1-3", "Dumnezeule, Dumnezeul meu, pe Tine Te caut dis-de-dimineață.\nÎnsetat-a de Tine sufletul meu, suspinat-a după Tine trupul meu,\nÎn pământ pustiu și neumblat și fără de apă. Așa în locul cel sfânt m-am arătat Ție, ca să văd puterea Ta și slava Ta."),
        new Prayer("Psalm 129, verses 1-2", "Out of the depths have I cried to thee, O Lord.\nO Lord, hearken to my voice; let thine ears be attentive to the voice of my supplication.",
                   "Psalmul 129, versetele 1-2", "Dintru adâncuri am strigat către Tine; Doamne! Doamne, auzi glasul meu!\nFie urechile Tale cu luare-aminte la glasul rugăciunii mele."),
        new Prayer("Psalm 140, verses 1-2", "O Lord, I have cried to thee; hear me: attend to the voice of my supplication, when I cry to thee.\nLet my prayer be set forth before thee as incense; the lifting up of my hands as an evening sacrifice.",
                   "Psalmul 140, versetele 1-2", "Doamne, strigat-am către Tine, auzi-mă; ia aminte la glasul rugăciunii mele, când strig către Tine.\nSă se îndrepteze rugăciunea mea ca tămâia înaintea Ta; ridicarea mâinilor mele, jertfă de seară."),
        new Prayer("Psalm 142, verse 8", "Cause me to hear thy mercy in the morning; for I have hoped in thee; make known to me, O Lord, the way wherein I should walk; for I have lifted up my soul to thee.",
                   "Psalmul 142, versetul 8", "Fă să aud dimineața mila Ta, că la Tine îmi este nădejdea. Arată-mi calea pe care voi merge, că la Tine am ridicat sufletul meu."),
        new Prayer("Psalm 15, verse 1", "Keep me, O Lord; for I have hoped in thee.",
                   "Psalmul 15, versetul 1", "Păzește-mă, Doamne, că spre Tine am nădăjduit."),
        new Prayer("Psalm 117, verse 24", "This is the day which the Lord has made: let us exult and rejoice in it.",
                   "Psalmul 117, versetul 24", "Aceasta este ziua pe care a făcut-o Domnul, să ne bucurăm și să ne veselim întru ea."),
        new Prayer("Psalm 102, verses 1-2", "Bless the Lord, O my soul; and all that is within me, bless his holy name.\nBless the Lord, O my soul, and forget not all his praises:",
                   "Psalmul 102, versetele 1-2", "Binecuvintează, suflete al meu, pe Domnul și toate cele dinlăuntrul meu, numele cel sfânt al Lui.\nBinecuvintează, suflete al meu, pe Domnul și nu uita toate răsplătirile Lui."),
        new Prayer("Psalm 85, verses 1-2", "O Lord, incline thine ear, and hearken to me; for I am poor and needy.\nPreserve my soul, for I am holy; save thy servant, O God, who hopes in thee.",
                   "Psalmul 85, versetele 1-2", "Pleacă, Doamne, urechea Ta și mă auzi, că sărac și necăjit sunt eu.\nPăzește sufletul meu, căci cuvios sunt; mântuiește, Dumnezeul meu, pe robul Tău, pe cel ce nădăjduiește în Tine."),
        new Prayer("Psalm 118, verse 105", "Thy law is a lamp to my feet, and a light to my paths.",
                   "Psalmul 118, versetul 105", "Făclie picioarelor mele este legea Ta și lumină cărărilor mele."),
        new Prayer("Psalm 41, verses 1-2", "As the hart earnestly desires the fountains of water, so my soul earnestly longs for thee, O God.\nMy soul has thirsted for the living God: when shall I come and appear before God?",
                   "Psalmul 41, versetele 1-2", "În ce chip dorește cerbul izvoarele apelor, așa Te dorește sufletul meu pe Tine, Dumnezeule.\nÎnsetat-a sufletul meu de Dumnezeul cel viu; când voi veni și mă voi arăta feței lui Dumnezeu?"),
        new Prayer("Psalm 69, verse 1", "Draw nigh, O God, to my help.",
                   "Psalmul 69, versetul 1", "Dumnezeule, spre ajutorul meu ia aminte! Doamne, să-mi ajuți mie grăbește-Te!"),
        new Prayer("Psalm 8, verse 1", "O Lord, our Lord, how wonderful is thy name in all the earth! for thy magnificence is exalted above the heavens.",
                   "Psalmul 8, versetul 1", "Doamne, Dumnezeul nostru, cât de minunat este numele Tău în tot pământul! Că s-a înălțat slava Ta, mai presus de ceruri."),
        new Prayer("Psalm 99, verses 1-2", "Make a joyful noise to the Lord, all the earth.\nServe the Lord with gladness; come before his presence with exultation.\nKnow that the Lord he is God; he made us, and not we ourselves; we are his people, and the sheep of his pasture.",
                   "Psalmul 99, versetele 1-2", "Strigați Domnului tot pământul, slujiți Domnului cu veselie, intrați înaintea Lui cu bucurie.\nCunoașteți că Domnul, El este Dumnezeul nostru; El ne-a făcut pe noi și nu noi."),
        new Prayer("Psalm 24, verses 1-2", "To thee, O Lord, have I lifted up my soul.\nO my God, I have trusted in thee: let me not be confounded, neither let mine enemies laugh me to scorn.",
                   "Psalmul 24, versetele 1-2", "Către Tine, Doamne, am ridicat sufletul meu, Dumnezeul meu.\nSpre Tine am nădăjduit, să nu fiu rușinat în veac, nici să râdă de mine vrăjmașii mei."),
        new Prayer("Psalm 103, verse 25", "How great are thy works, O Lord! in wisdom hast thou wrought them all: the earth is filled with thy creation.",
                   "Psalmul 103, versetul 25", "Cât s-au mărit lucrurile Tale, Doamne, toate cu înțelepciune le-ai făcut! Umplutu-s-a pământul de zidirea Ta."),
        new Prayer("Psalm 53, verse 1", "Save me, O God, by thy name, and judge me by thy might.",
                   "Psalmul 53, versetul 1", "Dumnezeule, întru numele Tău mântuiește-mă și întru puterea Ta mă judecă."),
        new Prayer("Psalm 150, verse 6", "Let every thing that has breath praise the Lord.",
                   "Psalmul 150, versetul 6", "Toată suflarea să laude pe Domnul!"),
    };
}
